#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> block_sums(max_threads + 1, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        long long local_sum = 0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += x[i];
        }
        block_sums[tid] = local_sum;

        #pragma omp barrier

        #pragma omp single
        {
            block_sums[nt] = 0;
            for (int t = nt - 1; t >= 0; --t) {
                block_sums[t] += block_sums[t + 1];
            }
        }

        #pragma omp barrier

        long long suffix = block_sums[tid + 1];
        for (std::size_t i = start; i < end; ++i) {
            suffix += x[i];
            output[i] = static_cast<int>(suffix);
        }
    }
}
